/* NORDAP – theory library (curated) for Flight Intelligence: aviation THEORY only, never rules.
   Organised by the EASA theoretical-knowledge subjects (081 Principles of Flight, 050 Meteorology, 022 Instrumentation), which set
   what is covered and how deep. Each entry is NORDAP's own explanation in EASA/ICAO terms and units (hPa, °C, ft, kt, ISA),
   written from these sources:
     - FAA Pilot's Handbook of Aeronautical Knowledge, FAA-H-8083-25C (a U.S. Government work, free to use): only the physics
       and understanding. Everything regulatory or U.S.-specific (14 CFR, AIM, U.S. airspace, U.S. weather categories,
       °F/inHg) is left out on purpose.
     - NORDAP's own Virtual Labs (lab: the page that shows it).
   RULES ARE NEVER TAKEN FROM HERE. Rules, limits and minima come only from the EASA rules library (easa.js, cited [E1]…).
   tests/theory.test.mjs fails if an entry contains regulatory wording or U.S. units.
   Cited in answers as [T1], [T2]… */
(function(G){
'use strict';
const FAA='https://www.faa.gov/regulationspolicies/handbooksmanuals/aviation/phak/';
const SRC={
  ch4:{n:'FAA PHAK (FAA-H-8083-25C) ch. 4, Principles of Flight',u:FAA+'chapter-4-principles-flight'},
  ch5:{n:'FAA PHAK (FAA-H-8083-25C) ch. 5, Aerodynamics of Flight',u:FAA+'chapter-5-aerodynamics-flight'},
  ch8:{n:'FAA PHAK (FAA-H-8083-25C) ch. 8, Flight Instruments',u:FAA+'chapter-8-flight-instruments'},
  ch12:{n:'FAA PHAK (FAA-H-8083-25C) ch. 12, Weather Theory',u:FAA+'chapter-12-weather-theory'}
};
const SUBJ={
  '081':{en:'081 Principles of Flight',no:'081 Flyteori (Principles of Flight)'},
  '050':{en:'050 Meteorology',no:'050 Meteorologi'},
  '022':{en:'022 Instrumentation',no:'022 Instrumentlære'}
};
const I=(id,subj,o)=>Object.assign({id,subj},o);
const items=[
/* ================= 081 PRINCIPLES OF FLIGHT ================= */
I('081-atmosphere','081',{title:{en:'The atmosphere and ISA',no:'Atmosfæren og ISA'},src:'ch4',lab:'airdata.html',
 kw:'atmosphere isa standard atmosphere 1013.25 15 °c lapse rate 1.98 tropopause 36090 11 km density pressure temperature atmosfære standardatmosfære tetthet trykk temperatur',
 en:'The International Standard Atmosphere (ISA) is the reference used for instruments and performance: at mean sea level 1013.25 hPa, +15 °C and a density of 1.225 kg/m³. Temperature falls about 1.98 °C per 1000 ft (6.5 °C per km) up to the tropopause at 11 km (36 090 ft), where it stays at −56.5 °C. Pressure falls roughly 1 hPa per 27–30 ft near the ground, less per foot higher up. Real days differ from ISA, so altimeters and performance charts work with deviations from it (ISA +10 means 10 °C warmer than standard at that level).'}),
I('081-density','081',{title:{en:'Air density and density altitude',no:'Lufttetthet og tetthetshøyde'},src:'ch4',lab:'airdata.html',
 kw:'density altitude pressure altitude hot high humid performance take-off climb thin air tetthetshøyde trykkhøyde varm fuktig ytelse',
 en:'Density altitude is the altitude in the ISA at which the air has the same density as the air you are in. High elevation, high temperature and high humidity all lower the density, so the density altitude rises. Lower density means the wing needs a higher true airspeed for the same lift, a propeller or engine produces less thrust, and take-off run and climb get worse, even though the indicated airspeeds for take-off stay the same. Rule of thumb: density altitude ≈ pressure altitude + 120 ft for each °C above ISA. Humid air is lighter than dry air because water vapour is lighter than nitrogen and oxygen.'}),
I('081-bernoulli','081',{title:{en:'How a wing makes lift',no:'Hvordan en vinge lager løft'},src:'ch4',lab:'tunnel.html',
 kw:'lift bernoulli newton pressure difference airflow downwash circulation upper surface low pressure løft trykkforskjell nedvask hvordan flyr et fly',
 en:'A wing makes lift by turning the airflow downwards. The shape and angle of attack make the air over the upper surface speed up and its pressure drop, while the pressure under the wing rises slightly; the pressure difference over the whole wing is the lift. The same event seen from Newton\'s third law: the wing pushes air down (downwash), so the air pushes the wing up. Bernoulli (faster flow, lower static pressure) and Newton are two descriptions of one flow, not competing theories. The popular "equal transit time" explanation is wrong: air over the top arrives at the trailing edge well before the air underneath.'}),
I('081-lift-equation','081',{title:{en:'The lift formula',no:'Løfteformelen'},src:'ch4',lab:'tunnel.html',
 kw:'lift formula equation cl coefficient of lift dynamic pressure q half rho v squared wing area speed doubled four times løfteformel løftekoeffisient dynamisk trykk',
 en:'Lift = CL × ½ρV² × S. CL (lift coefficient) depends on angle of attack and wing shape (flaps change it); ½ρV² is the dynamic pressure (ρ air density, V true airspeed); S is the wing area. Because speed is squared, doubling the speed gives four times the lift at the same angle of attack. In level flight lift must equal weight, so a slower speed needs a higher CL, which means a higher angle of attack, up to the stall. The indicated airspeed measures dynamic pressure, which is why the same IAS gives the same lift at any altitude.'}),
I('081-aoa','081',{title:{en:'Angle of attack and the airfoil',no:'Angrepsvinkel og vingeprofil'},src:'ch4',lab:'tunnel.html',
 kw:'angle of attack aoa alpha chord line relative airflow camber airfoil leading edge trailing edge angle of incidence pitch attitude angrepsvinkel vingeprofil korde krumning innfallsvinkel',
 en:'The chord line runs from leading edge to trailing edge; camber is the curvature of the airfoil. The angle of attack (AoA) is the angle between the chord line and the relative airflow, the direction the air comes from. It is not the pitch attitude and not the angle of incidence (the fixed angle at which the wing is mounted on the fuselage): in a descent the nose can point at the horizon while the AoA is high. Lift rises roughly linearly with AoA until near the critical angle (typically 15–20° for a light-aircraft wing without high-lift devices), where the flow separates and the wing stalls.'}),
I('081-drag','081',{title:{en:'Drag: parasite and induced',no:'Motstand: parasitt- og indusert motstand'},src:'ch5',lab:'forces.html',
 kw:'drag parasite drag form drag skin friction interference drag induced drag total drag curve vmd speed squared motstand parasittmotstand formmotstand friksjonsmotstand indusert motstand',
 en:'Total drag has two parts. Parasite drag is everything that does not come from making lift: form (pressure) drag, skin friction and interference drag where parts meet. It rises with the square of the speed. Induced drag is the price of lift: the wing tilts its lift slightly backwards because of the downwash and tip vortices. It is largest at high angle of attack, so it falls as speed rises (roughly with 1/V²). Adding the two gives a U-shaped total drag curve; the bottom is the minimum-drag speed (Vmd), which is also the speed of the best lift/drag ratio.'}),
I('081-vortices','081',{title:{en:'Wingtip vortices and induced drag',no:'Vingespissvirvler og indusert motstand'},src:'ch5',lab:'tunnel.html',
 kw:'wingtip vortex vortices induced drag aspect ratio winglets downwash high pressure below low pressure above heavy clean slow vingespissvirvel virvler sideforhold winglet',
 en:'The higher pressure under the wing and lower pressure above it make air spill around the tips, forming a vortex behind each tip. The vortices increase the downwash, which tilts the lift backwards: that backward part is induced drag. They are strongest when the wing works hardest: heavy, clean (flaps up) and slow. A long, slender wing (high aspect ratio) and winglets reduce induced drag, which is why gliders and long-range airliners have them.'}),
I('081-ld','081',{title:{en:'Lift/drag ratio and best glide',no:'Løft/motstand-forhold og beste glid'},src:'ch5',lab:'forces.html',
 kw:'lift drag ratio l/d glide best glide speed glide ratio engine failure weight wind glide distance glidetall glideforhold beste glidefart motorstans',
 en:'The lift/drag ratio (L/D) tells how much lift the wing makes per unit of drag. With the engine off, the glide ratio equals the L/D: an L/D of 10 means about 10 NM forward for each NM of height (in still air). The best L/D is at one angle of attack, flown as the best-glide speed. A heavier aircraft has the same best glide angle but must fly faster to hold that angle of attack, so it covers the same distance in less time. A headwind shortens the distance over the ground; a tailwind lengthens it.'}),
I('081-ground-effect','081',{title:{en:'Ground effect',no:'Bakkeeffekt'},src:'ch5',lab:'tunnel.html',
 kw:'ground effect floating flare take-off one wingspan induced drag reduced lift off too early bakkeeffekt flyte landing avgang',
 en:'Within about one wingspan of the ground, the ground blocks the downwash and the tip vortices. Induced drag falls and the wing gives more lift at the same angle of attack, so the aircraft tends to float in the flare, especially if it comes in fast. On take-off an aircraft can lift off at a speed that is too low to climb out of ground effect; as it climbs, induced drag returns and it may sink back. The static pressure near the static ports also changes, so the airspeed indicator can read slightly differently close to the ground.'}),
I('081-stall','081',{title:{en:'The stall',no:'Steiling'},src:'ch5',lab:'tunnel.html',
 kw:'stall stalls stalling wing stalls steiler steile steilet vinge vingen critical angle of attack separation buffet stall warning recovery reduce angle of attack any speed any attitude steiling kritisk angrepsvinkel strømningsavløsning buffeting gjenoppretting',
 en:'A wing stalls when it exceeds the critical angle of attack: the airflow can no longer follow the upper surface, separates, and lift falls while drag rises sharply. A stall is about angle of attack, not speed: it can happen at any airspeed and in any attitude, for example when pulling hard in a steep turn. Warnings are buffet, a stall-warning system and mushy controls. The recovery is always to reduce the angle of attack first (pitch down / release back pressure), then level the wings and add power as the aircraft type requires.'}),
I('081-stall-speed','081',{title:{en:'Stall speed: weight, load factor and configuration',no:'Steilefart: masse, lastfaktor og konfigurasjon'},src:'ch5',lab:'stability.html',
 kw:'stall speed vs weight load factor bank angle turn square root flaps cg forward aft power steilefart masse lastfaktor krengning sving klaffer tyngdepunkt',
 en:'The stall happens at the same angle of attack, but the speed at which it is reached changes. Stall speed rises with the square root of the load factor: in a level 60° banked turn (load factor 2) it is about 1.41 times the wings-level stall speed. It rises with the square root of the weight too. Flaps lower it (higher maximum CL). A forward centre of gravity raises it slightly, because the tail must push down harder and the wing must carry that extra load. Power on lowers the indicated stall speed a little.'}),
I('081-load-factor','081',{title:{en:'Load factor and turns',no:'Lastfaktor og svinger'},src:'ch5',lab:'stability.html',
 kw:'load factor g n turn bank angle 1/cos rate of turn radius of turn standard rate 3 degrees per second v-n diagram manoeuvring speed lastfaktor sving krengning svingrate svingradius',
 en:'Load factor (n) is lift divided by weight, felt as "g". In a level turn the lift must be tilted, so it has to grow: n = 1/cos(bank). 30° gives 1.15 g, 45° 1.41 g, 60° 2 g. At a given true airspeed, more bank gives a higher rate of turn and a smaller radius; at a given bank, a higher speed gives a larger radius and a lower rate. A rate-one turn is 3° per second (2 minutes for 360°); the bank it needs is roughly TAS/10 + 7 degrees. The structure is certified for a limited load factor, shown on the V-n diagram.'}),
I('081-high-lift','081',{title:{en:'Flaps, slats and high-lift devices',no:'Klaffer, slats og høyløftsinnretninger'},src:'ch5',lab:'tunnel.html',
 kw:'flaps slats slots high lift devices plain flap split flap slotted flap fowler leading edge camber clmax pitch change klaffer slats slisser høyløft',
 en:'Trailing-edge flaps increase the camber (and with Fowler flaps also the wing area), so the wing makes the same lift at a lower speed and the stall speed drops. They also add drag, which steepens the approach. Plain and split flaps are simple; slotted and Fowler flaps let high-energy air from below re-energise the upper surface and are more effective. Leading-edge slats and slots delay separation, so the wing reaches a higher critical angle of attack. Extending or retracting flaps changes the pitch and the stall speed, which is why it is done in steps and within the flap speeds.'}),
I('081-boundary-layer','081',{title:{en:'Boundary layer and flow separation',no:'Grensesjikt og strømningsavløsning'},src:'ch5',lab:'tunnel.html',
 kw:'boundary layer laminar turbulent transition separation vortex generators contamination ice frost grensesjikt laminær turbulent virvelgeneratorer',
 en:'Right next to the skin the air slows down to zero in a thin boundary layer. It starts laminar (smooth, low friction) and becomes turbulent further back; a turbulent layer has more friction but more energy, so it stays attached longer against rising pressure. Separation, the start of the stall, begins when the boundary layer runs out of energy. Vortex generators stir energy into it to delay separation. Frost, ice or dirt on the leading edge roughen the boundary layer and can cut maximum lift a lot, which is why even a thin layer of frost is dangerous.'}),
I('081-four-forces','081',{title:{en:'The four forces, climb and descent',no:'De fire kreftene, stigning og sink'},src:'ch5',lab:'forces.html',
 kw:'four forces lift weight thrust drag climb excess thrust excess power vx vy angle rate of climb descent equilibrium de fire kreftene stigning beste stigevinkel beste stigerate',
 en:'In steady flight the forces balance: lift against weight, thrust against drag. An aircraft climbs because of excess thrust or power, not excess lift: in a steady climb lift is actually slightly less than weight, and part of the weight acts backwards along the path. The best angle of climb (Vx) is where the excess thrust is greatest; the best rate of climb (Vy) is where the excess power is greatest, so Vx is lower than Vy. As altitude rises the excess shrinks and Vx and Vy move towards each other until they meet at the absolute ceiling.'}),
I('081-left-turning','081',{title:{en:'Propeller effects: torque, slipstream, P-factor, gyroscopic',no:'Propelleffekter: dreiemoment, slipstrøm, P-faktor, gyro'},src:'ch5',lab:'propeller.html',
 kw:'torque slipstream p-factor asymmetric blade effect gyroscopic precession propeller yaw rudder left turning tendency critical engine dreiemoment slipstrøm propell gir ror kritisk motor',
 en:'A propeller turning clockwise seen from behind (most Western engines) makes the aircraft yaw and roll left in four ways. Torque rolls the aircraft opposite to the propeller rotation. The spiralling slipstream hits the left side of the fin. P-factor (asymmetric blade effect): at high angle of attack the descending blade has a higher angle of attack and more thrust than the ascending one, so thrust moves to the right side of the disc. Gyroscopic precession acts when the propeller disc is tilted, for example when a tailwheel aircraft raises its tail. All are largest at high power and low speed, so rudder is needed on take-off and in the climb. On a twin, P-factor is what makes one engine the critical engine.'}),
I('081-stability-static','081',{title:{en:'Static and dynamic stability',no:'Statisk og dynamisk stabilitet'},src:'ch5',lab:'stability.html',
 kw:'stability static dynamic positive neutral negative oscillation damped phugoid short period stabilitet statisk dynamisk dempet svingning',
 en:'Static stability is the first reaction after a disturbance: positive means the aircraft tends back towards where it was, neutral means it stays in the new position, negative means it moves further away. Dynamic stability is what happens over time: whether the oscillations die out (positive), stay the same (neutral) or grow (negative). An aircraft can be statically stable but dynamically unstable. In pitch there is a slow, lightly damped speed-and-height oscillation (phugoid) and a fast, well-damped short-period motion.'}),
I('081-longitudinal','081',{title:{en:'Longitudinal stability and the centre of gravity',no:'Lengdestabilitet og tyngdepunktet'},src:'ch5',lab:'stability.html',
 kw:'longitudinal stability pitch centre of gravity cg forward aft limit neutral point tailplane download trim elevator force static margin lengdestabilitet tyngdepunkt fremre bakre grense nøytralpunkt haleflate',
 en:'Pitch stability depends on where the centre of gravity (CG) is relative to the neutral point. With the CG ahead of it, a nose-up disturbance increases the tailplane\'s lift more than the wing\'s about the CG, which pitches the nose back down. A forward CG gives more stability, heavier elevator forces, a higher stall speed and slightly more drag, because the tail pushes down harder. An aft CG gives lighter forces, less stability and, behind the aft limit, an aircraft that can become uncontrollable, especially in a stall or spin. That is why CG limits matter.'}),
I('081-lateral','081',{title:{en:'Lateral and directional stability, Dutch roll and spiral',no:'Side- og retningsstabilitet, Dutch roll og spiral'},src:'ch5',lab:'stability.html',
 kw:'lateral stability dihedral high wing keel effect sweepback directional stability fin weathercock dutch roll spiral instability yaw damper sidestabilitet v-form retningsstabilitet halefinne spiral girdemper',
 en:'Lateral (roll) stability comes mainly from dihedral, a high wing position and sweepback: in a sideslip the lower wing meets the air at a higher angle of attack and rolls the aircraft back. Directional (yaw) stability comes from the fin, which turns the nose into the relative wind like a weathervane. The balance between the two decides the dynamic behaviour. Strong roll stability with weaker directional stability gives Dutch roll, a combined yaw-and-roll oscillation, common on swept-wing jets and damped by a yaw damper. Strong directional with weak roll stability gives spiral instability: a slowly tightening, descending turn if left alone.'}),
I('081-adverse-yaw','081',{title:{en:'Adverse yaw and coordinated turns',no:'Ugunstig giring og koordinerte svinger'},src:'ch5',lab:'stability.html',
 kw:'adverse yaw aileron drag frise ailerons differential ailerons coordination rudder slip skid ball ugunstig giring balanse skrens slipp kule',
 en:'When you roll with the ailerons, the down-going aileron raises the lift and therefore the induced drag of the rising wing, which yaws the nose away from the turn: adverse yaw. Differential and Frise ailerons reduce it, and rudder in the direction of the turn cancels it. The slip/skid ball shows the result: "step on the ball" to centre it. A skidding turn at low speed (too much rudder, ball outside) is the classic set-up for a spin, because the outer wing gets more lift and the inner wing nears the stall.'}),
I('081-spin','081',{title:{en:'Spins',no:'Spinn'},src:'ch5',lab:'stability.html',
 kw:'spin autorotation incipient developed recovery rudder opposite yaw stall one wing more stalled spiral dive difference spinn autorotasjon',
 en:'A spin is an autorotation that starts when an aircraft is stalled and yawed at the same time: one wing is more deeply stalled, has less lift and more drag, so the aircraft rolls and yaws towards it and keeps going. Unlike a spiral dive, the airspeed in a spin stays low and the wing remains stalled. It goes through an incipient phase and a developed phase. The general recovery is power to idle, ailerons neutral, full rudder against the rotation, then elevator forward to break the stall, and recover from the dive once the rotation stops; the aircraft\'s own AFM procedure always takes precedence.'}),
I('081-wake','081',{title:{en:'Wake turbulence',no:'Vaketurbulens'},src:'ch5',lab:'hazards.html',
 kw:'wake turbulence wake vortex heavy clean slow sink drift crosswind avoid above flight path touchdown point rotation point vaketurbulens kjølvann virvler tunge fly',
 en:'Every wing leaves two counter-rotating vortices behind it; they are strongest behind heavy, clean, slow aircraft, so take-off and landing are the critical phases. The vortices sink below the generating aircraft\'s path, typically several hundred feet per minute, and level off some 500–900 ft below it. Near the ground they spread sideways at a few knots; a light crosswind of about 1–5 kt can hold the upwind vortex on the runway. To avoid them, stay at or above the heavier aircraft\'s flight path, land beyond its touchdown point and lift off before its rotation point. Wake encounters can roll a light aircraft beyond its control authority.'}),
I('081-mach','081',{title:{en:'High-speed flight: Mach number and shock waves',no:'Høyhastighet: Machtall og sjokkbølger'},src:'ch5',lab:'highspeed.html',
 kw:'mach number speed of sound critical mach mcrit shock wave transonic compressibility wave drag drag divergence machtall lydhastighet kritisk mach sjokkbølge transonisk bølgemotstand',
 en:'The Mach number is true airspeed divided by the local speed of sound, which depends only on temperature: about 661 kt at ISA sea level and 573 kt in the −56.5 °C air above the tropopause. Air speeds up over the wing, so local flow reaches Mach 1 before the aircraft does; the free-stream Mach number at which that first happens is the critical Mach number (Mcrit). Above it a shock wave forms on the upper surface, causing wave drag, possible flow separation behind the shock (buffet) and changes in trim. Subsonic jets cruise just below the drag-divergence Mach number.'}),
I('081-sweep','081',{title:{en:'Swept wings',no:'Pilformede vinger'},src:'ch5',lab:'highspeed.html',
 kw:'sweepback swept wing mcrit tip stall pitch up dutch roll spanwise flow wing fences pilform sweep vinge tippsteiling',
 en:'Sweeping the wing back means the air "sees" only the component of speed at right angles to the leading edge, so the wing behaves as if it flies slower and Mcrit rises. The price: less lift per degree of angle of attack, a higher stall speed (so slats and big flaps are needed), spanwise flow towards the tips and a tendency to stall at the tips first. A tip stall on a swept wing moves the lift forward and can pitch the nose up further into the stall. Sweep also adds roll stability and is one reason swept-wing jets have a Dutch-roll tendency.'}),
I('081-coffin','081',{title:{en:'Mach buffet, high-speed stall and the coffin corner',no:'Machbuffeting, høyhastighetssteiling og «coffin corner»'},src:'ch5',lab:'highspeed.html',
 kw:'mach buffet low speed buffet high speed buffet coffin corner buffet margin high altitude stall mmo mach tuck tuck under bank 1.3 g buffeting kiste høyde',
 en:'At high altitude the low-speed (stall) buffet speed rises because the air is thin, and the high-speed (Mach) buffet comes down in indicated terms because the speed of sound in true-airspeed terms is low. The two close in on each other, the "coffin corner", and the margin shrinks further with weight and with load factor in turns or turbulence. Operators plan a buffet margin (often 1.3 g) for this reason. Mach tuck is the nose-down pitch as the centre of pressure moves aft with shock formation; Mach trim systems counter it.'}),
I('081-weight-effects','081',{title:{en:'Effect of weight on performance',no:'Effekten av masse på ytelse'},src:'ch5',lab:'forces.html',
 kw:'weight mass heavy performance stall speed take-off distance climb rate range endurance glide masse tung ytelse avgangsdistanse rekkevidde',
 en:'More weight needs more lift, so at every point the wing works at a higher angle of attack for a given speed. The results: higher stall and reference speeds, longer take-off and landing distances, lower climb rate and ceiling, more fuel burn, and higher loads on the structure in turns and gusts. The best glide angle does not change with weight, but the best-glide speed rises. Speeds such as Vref scale with the square root of the mass.'}),

/* ================= 022 INSTRUMENTATION ================= */
I('022-pitot-static','022',{title:{en:'The pitot-static system',no:'Pitot-statisk system'},src:'ch8',lab:'airdata.html',
 kw:'pitot static pitot tube static port total pressure static pressure dynamic pressure airspeed indicator altimeter vsi alternate static pitotrør statisk port totaltrykk statisk trykk',
 en:'The pitot tube faces the airflow and senses total pressure (static + dynamic); the static ports on the side of the fuselage sense the static pressure of the surrounding air. The airspeed indicator uses both (total minus static = dynamic pressure); the altimeter and the vertical speed indicator use static pressure only. Pitot heat prevents icing of the tube. If the static ports block, an alternate static source (often inside an unpressurised cabin) can be selected; cabin pressure is usually slightly lower than outside, so the altimeter and airspeed then read a little high.'}),
I('022-blockage','022',{title:{en:'Pitot and static blockages',no:'Blokkering av pitot og statisk'},src:'ch8',lab:'airdata.html#blockages',
 kw:'blocked pitot blocked static drain hole icing altimeter frozen asi acts like altimeter vsi zero airspeed increases in climb blokkert pitot blokkert statisk ising',
 en:'Pitot blocked but its drain open: the airspeed falls to zero. Pitot tube and drain both blocked: the trapped pressure makes the airspeed indicator act like an altimeter, reading more in a climb and less in a descent, while the true speed may be quite different (a dangerous trap in a climb). Static ports blocked: the altimeter freezes at the altitude of blockage, the VSI shows zero, and the airspeed reads low in a climb and high in a descent. The cure for a static blockage is the alternate static source or, as a last resort in some aircraft, breaking the VSI glass.'}),
I('022-airspeeds','022',{title:{en:'IAS, CAS, EAS and TAS',no:'IAS, CAS, EAS og TAS'},src:'ch8',lab:'airdata.html',
 kw:'indicated airspeed calibrated airspeed equivalent airspeed true airspeed ias cas eas tas ground speed position error compressibility tas increases with altitude 2 percent per 1000 ft indikert kalibrert sann fart bakkefart',
 en:'IAS is what the instrument shows. Correcting it for instrument and position (installation) errors gives CAS. Correcting CAS for compressibility, which matters above about 200 kt and at altitude, gives EAS. Correcting for air density gives TAS, the real speed through the air. TAS is higher than CAS at altitude, roughly 2 % per 1000 ft. Ground speed is TAS corrected for wind. Lift, the stall and structural limits follow IAS/EAS, while navigation and the Mach number follow TAS.'}),
I('022-asi-markings','022',{title:{en:'Airspeed indicator markings',no:'Markeringer på fartsmåleren'},src:'ch8',lab:'airdata.html',
 kw:'white arc green arc yellow arc red line vso vs1 vfe vno vne caution range airspeed indicator markings hvit bue grønn bue gul bue rød strek',
 en:'On a light aircraft the airspeed indicator shows the main speeds as arcs: the white arc is the flap operating range (from the landing-configuration stall speed Vso to the maximum flap speed Vfe), the green arc the normal operating range (from Vs1 to Vno, the maximum structural cruising speed), the yellow arc the caution range, flown only in smooth air, and the red line Vne, never exceed. A twin also has a red radial line for the minimum control speed with one engine out (Vmca) and a blue line for the best single-engine rate of climb (Vyse). The values themselves are aircraft-specific: take them from the AFM.'}),
I('022-altimeter','022',{title:{en:'The altimeter and altimeter settings',no:'Høydemåleren og høydemålerinnstillinger'},src:'ch8',lab:'airdata.html',
 kw:'altimeter aneroid capsule subscale qnh qfe standard 1013 pressure altitude flight level transition altitude high to low look out below 27 ft per hpa hoydemaler høydemåler aneroide innstilling',
 en:'The altimeter is an aneroid barometer: sealed capsules expand as the static pressure falls, and the pointers show the height above the pressure set in the subscale. With QNH set it shows altitude above mean sea level; with QFE, height above the aerodrome; with 1013.25 hPa, pressure altitude, used as flight levels. Near the ground 1 hPa is about 27–30 ft. Flying from high to low pressure without resetting makes the altimeter read too high, so you are lower than shown ("high to low, look out below"). The same applies when it is colder than ISA.'}),
I('022-temperature-error','022',{title:{en:'Temperature error of the altimeter',no:'Temperaturfeil på høydemåleren'},src:'ch8',lab:'airdata.html',
 kw:'temperature error cold temperature correction colder than isa altimeter reads high 4 percent per 10 degrees obstacle clearance low temperature temperaturfeil kald temperaturkorreksjon',
 en:'The altimeter is calibrated for the ISA temperature. In air colder than ISA the pressure falls faster with height, so the true altitude is lower than the altimeter shows; in warm air it is higher. The error grows with the height above the station where the altimeter setting comes from, roughly 4 % of that height for every 10 °C below ISA. In very cold weather this can eat into obstacle clearance on approaches and minimum altitudes, which is why cold-temperature corrections exist; how and when they are applied is a matter of the rules and the operator\'s procedures.'}),
I('022-altitudes','022',{title:{en:'Types of altitude',no:'Typer høyde'},src:'ch8',lab:'airdata.html',
 kw:'indicated altitude true altitude absolute altitude height pressure altitude density altitude agl amsl indikert høyde sann høyde trykkhøyde tetthetshøyde høyde over bakken',
 en:'Indicated altitude is what the altimeter shows with the current setting. True altitude is the real height above mean sea level. Absolute altitude (height) is the height above the ground below. Pressure altitude is what the altimeter shows with 1013.25 hPa set: the basis for flight levels and performance charts. Density altitude is pressure altitude corrected for non-standard temperature and decides aircraft performance. With the right QNH and an ISA temperature, indicated and true altitude are the same.'}),
I('022-vsi','022',{title:{en:'The vertical speed indicator',no:'Variometer (VSI)'},src:'ch8',lab:'airdata.html',
 kw:'vertical speed indicator vsi variometer rate of climb calibrated leak lag ivsi trend rate variometer stigehastighet forsinkelse',
 en:'The VSI compares the static pressure in a capsule with the pressure in the case, which leaks out slowly through a calibrated orifice. When you climb, the case pressure lags behind the falling outside pressure and the difference shows as a climb rate. It shows the trend at once but needs some seconds to settle on the exact rate (lag); an instantaneous VSI (IVSI) uses small accelerometer pumps to remove most of the lag. A blocked static source makes it read zero.'}),
I('022-gyro-principles','022',{title:{en:'Gyroscopic principles: rigidity and precession',no:'Gyroprinsipper: stivhet og presesjon'},src:'ch8',lab:'gyros.html',
 kw:'gyroscope rigidity in space precession vacuum electric gyro suction drift real wander apparent wander earth rate gyroskop stivhet presesjon vakuum drift',
 en:'A spinning rotor has rigidity in space: it keeps its orientation unless a force acts on it. When a force is applied, it reacts 90° further on in the direction of rotation: precession. Attitude and heading instruments use rigidity as a reference; the turn indicator uses precession. Gyros are driven by vacuum (suction) or electricity. Friction and imperfect balance make them drift (real wander), and the rotation of the Earth makes a gyro that is fixed in space appear to wander (apparent wander), which is why heading indicators must be realigned.'}),
I('022-attitude','022',{title:{en:'The attitude indicator',no:'Kunstig horisont'},src:'ch8',lab:'gyros.html',
 kw:'attitude indicator artificial horizon vertical gyro erection mechanism pitch bank acceleration error turning error vacuum failure ahrs kunstig horisont holdningsindikator',
 en:'The attitude indicator has a gyro spinning about a vertical axis, kept upright by an erection mechanism, with the aircraft symbol moving around the stable horizon. It shows pitch and bank directly and is the main instrument for flight by reference to instruments. Mechanical units can show small errors after accelerations (a false slight nose-up on take-off acceleration) and after prolonged turns, and they topple beyond their limits of pitch and bank. A failing vacuum system makes a vacuum attitude indicator slowly drift and tilt, which is why the suction gauge and a cross-check of other instruments matter. Glass cockpits use an AHRS with solid-state sensors instead.'}),
I('022-heading-indicator','022',{title:{en:'Heading indicator and slaved compasses',no:'Kursgyro og slavet kompass'},src:'ch8',lab:'gyros.html',
 kw:'heading indicator directional gyro di drift align with compass every 15 minutes flux valve flux gate slaved hsi rmi kursgyro kursindikator flux valve',
 en:'The heading indicator is a gyro with a horizontal spin axis that holds a heading reference without the swinging and turning errors of the magnetic compass. Because of real and apparent wander it drifts, so on a non-slaved unit you align it with the magnetic compass regularly (commonly every 10–15 minutes) in straight and level, unaccelerated flight. In a slaved system a flux valve (flux gate) senses the Earth\'s magnetic field and keeps the gyro aligned automatically; it feeds an HSI or RMI.'}),
I('022-turn-coordinator','022',{title:{en:'Turn coordinator and slip indicator',no:'Svingkoordinator og balansekule'},src:'ch8',lab:'gyros.html',
 kw:'turn coordinator turn and slip turn indicator rate one standard rate inclinometer ball slip skid coordination svingindikator svingkoordinator balansekule rate one',
 en:'The turn indicator uses gyroscopic precession to show rate of turn; the turn coordinator has its gyro tilted so it also reacts to roll rate, so it shows the start of a turn earlier. The marks show a rate-one (3° per second) turn; neither shows bank angle directly. Under it, the inclinometer ball shows coordination: ball to the inside of the turn is a slip (too little rudder or too much bank), ball to the outside a skid (too much rudder). Centre it with rudder on the side the ball is on.'}),
I('022-compass-errors','022',{title:{en:'Magnetic compass errors',no:'Magnetkompassets feil'},src:'ch8',lab:'gyros.html',
 kw:'magnetic compass variation deviation dip acceleration error turning error northerly southerly undershoot overshoot anders unos deviation card isogonic magnetkompass variasjon deviasjon inklinasjon akselerasjonsfeil svingfeil',
 en:'Variation is the angle between true and magnetic north and changes with position (shown on charts by isogonic lines). Deviation is the error caused by the aircraft\'s own magnetic fields and is listed on the deviation card. Magnetic dip makes the compass hang tilted towards the nearer pole, which causes two flight errors. In the northern hemisphere: accelerating on an east or west heading makes the compass show a turn towards north, decelerating a turn towards south (ANDS: accelerate north, decelerate south). In turns, it lags or even turns the wrong way through northerly headings and leads through southerly ones, so you roll out early on south and late on north (UNOS: undershoot north, overshoot south). The errors are largest at high latitudes such as Scandinavia, and reversed in the southern hemisphere.'}),
I('022-adc-ahrs','022',{title:{en:'Air data computer, AHRS and glass cockpits',no:'Air data computer, AHRS og glasscockpit'},src:'ch8',lab:'airdata.html',
 kw:'air data computer adc ahrs adahrs magnetometer solid state pfd mfd g1000 failure red x air data computer glasscockpit',
 en:'In a glass cockpit an air data computer (ADC) takes pitot pressure, static pressure and outside temperature and computes IAS, TAS, Mach, altitude, vertical speed and temperatures for the displays and the autopilot. An attitude and heading reference system (AHRS) uses solid-state rate sensors, accelerometers and a magnetometer instead of spinning gyros. If either fails, the affected data is removed (often shown with a red X) and you fly on the standby instruments or the remaining system. A blocked pitot or static source still fools an ADC in the same way as the old instruments.'}),

/* ================= 050 METEOROLOGY ================= */
I('050-pressure-wind','050',{title:{en:'Pressure systems and wind',no:'Trykksystemer og vind'},src:'ch12',lab:'pressure.html',
 kw:'high pressure low pressure anticyclone depression isobars pressure gradient coriolis geostrophic wind friction surface wind veer back buys ballot clockwise høytrykk lavtrykk isobarer trykkgradient corioliskraft geostrofisk vind friksjon dreier krymper',
 en:'Air moves from high to low pressure, but the Earth\'s rotation (Coriolis effect) deflects it, to the right in the northern hemisphere. Above the friction layer the wind ends up blowing along the isobars (geostrophic wind), clockwise around a high and anticlockwise around a low in the northern hemisphere; the closer the isobars, the stronger the wind. Near the surface friction slows the wind, Coriolis weakens, and the wind turns to blow partly across the isobars towards the low: the surface wind is backed and weaker than the wind at 2000 ft. With your back to the wind in the northern hemisphere, the low is on your left (Buys Ballot).'}),
I('050-local-winds','050',{title:{en:'Local winds: sea breeze, valley and katabatic winds',no:'Lokale vinder: sjøbris, dalvind og fallvind'},src:'ch12',lab:'pressure.html',
 kw:'sea breeze land breeze katabatic anabatic valley wind mountain wind fohn foehn venturi local wind sjøbris landbris fallvind katabatisk anabatisk føhn',
 en:'Local temperature differences drive local winds. On a sunny day the land warms faster than the sea, the air over land rises and a sea breeze blows onshore in the afternoon; at night the land cools and a weaker land breeze blows offshore. On slopes, air warmed by the sun flows uphill (anabatic) and cold, dense air drains downhill at night (katabatic), which can be strong and gusty down fjords and valleys. Wind forced through a gap or a valley speeds up (venturi). Air descending on the lee side of mountains warms adiabatically and gives the warm, dry föhn wind.'}),
I('050-moisture','050',{title:{en:'Humidity, dew point and saturation',no:'Fuktighet, duggpunkt og metning'},src:'ch12',lab:'clouds.html',
 kw:'humidity relative humidity dew point spread saturation condensation evaporation latent heat temperature dew point spread fog risk fuktighet relativ fuktighet duggpunkt duggpunktsdifferanse metning kondensasjon',
 en:'Relative humidity is how much water vapour the air holds compared with the most it can hold at that temperature. The dew point is the temperature to which the air must cool, at constant pressure, to become saturated; then condensation forms cloud, fog or dew. The smaller the spread between temperature and dew point, the closer the air is to saturation: a spread of 2–3 °C or less, especially with falling temperatures in the evening, warns of fog and low cloud. Condensation releases latent heat, which is the energy that drives cumulus and thunderstorms.'}),
I('050-stability','050',{title:{en:'Adiabatic lapse rates and atmospheric stability',no:'Adiabatiske temperaturgradienter og stabilitet'},src:'ch12',lab:'clouds.html',
 kw:'stability unstable stable air adiabatic dry adiabatic lapse rate 3 degrees saturated adiabatic 1.5 2 degrees environmental lapse rate inversion conditional instability cumulus stratus stabil ustabil luft adiabatisk temperaturgradient inversjon',
 en:'A rising parcel of air expands and cools adiabatically: about 3 °C per 1000 ft while unsaturated (dry adiabatic lapse rate) and about 1.5–2 °C per 1000 ft once saturated (saturated adiabatic), because condensation releases heat. Whether the air is stable depends on the environmental lapse rate, the actual temperature profile. If a lifted parcel ends up warmer than its surroundings it keeps rising: the air is unstable (cumulus, showers, good visibility outside showers, turbulence). If it ends up colder it sinks back: the air is stable (layer cloud, steady precipitation, poor visibility in haze or fog, smooth air). An inversion, temperature rising with height, is very stable and traps haze and pollution below it.'}),
I('050-clouds','050',{title:{en:'Clouds and cloud types',no:'Skyer og skytyper'},src:'ch12',lab:'clouds.html',
 kw:'cloud types cumulus stratus cirrus nimbostratus altostratus altocumulus cumulonimbus cb tcu towering cumulus low middle high cloud base skytyper cumulus stratus cirrus cumulonimbus skybase',
 en:'Clouds form when air is cooled to its dew point, usually by rising. They are grouped by height: low (stratus, stratocumulus, nimbostratus with its base low), middle (altostratus, altocumulus) and high (cirrus, cirrostratus, cirrocumulus, made of ice crystals), plus clouds of vertical development: cumulus, towering cumulus (TCU) and cumulonimbus (CB). Heaped (cumuliform) clouds mean unstable air, rising currents and turbulence; layered (stratiform) clouds mean stable air and smooth flight. The cumulus base can be estimated from the spread: about 400 ft for each °C between temperature and dew point.'}),
I('050-fog','050',{title:{en:'Fog and mist',no:'Tåke og dis'},src:'ch12',lab:'clouds.html',
 kw:'fog radiation fog advection fog upslope fog steam fog frontal fog mist visibility clear night light wind tåke strålingståke adveksjonståke sjørøyk dis sikt',
 en:'Fog is a cloud at the ground that reduces visibility below 1000 m (mist when visibility is still 1000 m or more). Radiation fog forms over land on clear nights with light wind and moist air, when the ground cools the air above it to its dew point; it is often thickest around sunrise and burns off as the sun warms the surface. Advection fog forms when moist air moves over a colder surface, such as warm sea air over a cold sea or cold land, and can persist with stronger winds, day and night. Upslope fog comes from moist air forced up a slope; steam fog (sea smoke) from very cold air over much warmer water; frontal fog from rain falling into cold air ahead of a warm front.'}),
I('050-air-masses','050',{title:{en:'Air masses',no:'Luftmasser'},src:'ch12',lab:'fronts.html',
 kw:'air mass polar arctic tropical maritime continental source region modification cold air mass warm air mass luftmasse polar arktisk tropisk maritim kontinental',
 en:'An air mass is a large body of air with fairly even temperature and humidity, taking its properties from where it formed: polar or arctic (cold) versus tropical (warm), maritime (moist) versus continental (dry). As it moves it is changed by the surface under it. Cold air moving over a warmer surface is heated from below and becomes unstable: cumulus, showers, good visibility and turbulence, typical of maritime polar air over Norway. Warm air moving over a colder surface is cooled from below and becomes stable: stratus, drizzle, fog and poor visibility.'}),
I('050-fronts','050',{title:{en:'Fronts: warm, cold, occluded',no:'Fronter: varm-, kald- og okklusjonsfront'},src:'ch12',lab:'fronts.html',
 kw:'front warm front cold front occluded front occlusion stationary front frontal weather wind shift pressure trough sequence cirrus altostratus nimbostratus squall line frontal passage front varmfront kaldfront okklusjon stasjonær front frontpassasje',
 en:'A front is the boundary between two air masses. At a warm front, warm air rides slowly up over cold air on a shallow slope: the weather arrives gradually over hundreds of kilometres, with cirrus, then thickening altostratus and nimbostratus, a long period of rain or snow, low cloud and poor visibility, with freezing rain possible where warm air lies over sub-zero air. A cold front is steeper and faster: a narrower band of cumulus and possibly cumulonimbus, heavy showers, gusts and turbulence, then clearer, colder air. At any front passage the wind veers (northern hemisphere), the temperature and dew point change and the pressure stops falling. An occlusion forms when the cold front catches up with the warm front and can combine the weather of both, often with embedded CBs.'}),
I('050-thunderstorms','050',{title:{en:'Thunderstorms',no:'Tordenvær'},src:'ch12',lab:'storms.html',
 kw:'thunderstorm thunderstorms tordenbyge tordenbyger torden cumulonimbus cb life cycle cumulus stage mature stage dissipating stage updraft downdraft anvil hail lightning gust front squall line embedded cb conditions moisture instability lifting tordenvær cumulonimbus livssyklus oppvind nedvind ambolt hagl lyn byge',
 en:'A thunderstorm needs three things: moist air, an unstable atmosphere and a trigger that lifts the air (surface heating, a front, orography or converging winds). It goes through a cumulus stage (updrafts only, growing cloud), a mature stage (updrafts and downdrafts side by side, heavy precipitation, lightning, hail, the most violent turbulence and a gust front spreading out at the surface) and a dissipating stage (mainly downdrafts, the anvil spreading out). One cell typically lives about an hour, but storms in lines or clusters can last much longer. Severe turbulence, hail and wind shear can extend well outside the visible cloud; embedded CBs hidden in layer cloud are especially dangerous. Avoidance distances and procedures come from the operator, not from this library.'}),
I('050-windshear','050',{title:{en:'Wind shear and microbursts',no:'Vindskjær og mikroburst'},src:'ch12',lab:'storms.html',
 kw:'wind shear windshear microburst downburst performance increasing decreasing headwind loss tailwind low level wind shear inversion escape manoeuvre vindskjær mikroburst fallvind',
 en:'Wind shear is a change in wind speed or direction over a short distance. Near the ground it is most dangerous on take-off and approach. A microburst is a concentrated downdraft from a convective cloud that spreads out at the ground: flying into it you first meet an increasing headwind (airspeed and performance rise), then a strong downdraft and finally an increasing tailwind that makes the airspeed and lift fall sharply, possibly faster than the aircraft can accelerate. Microbursts typically last only minutes and cover a few kilometres. Shear also occurs across fronts, under low-level jets and at the top of a temperature inversion. The escape manoeuvre is aircraft-specific and comes from the AFM/operator.'}),
I('050-icing','050',{title:{en:'Airframe icing',no:'Ising på flyet'},src:'ch12',lab:'hazards.html',
 kw:'icing airframe ice rime ice clear ice mixed ice freezing rain supercooled droplets sld 0 to -15 frost carburettor ice induction icing ising rimis klaris underkjølte dråper underkjølt regn frost forgasserising',
 en:'Airframe icing needs visible moisture (cloud or rain) and a surface at or below 0 °C; the droplets are supercooled liquid water that freezes on impact. Small droplets freeze quickly to rough, white rime ice, typical in stratiform cloud. Large droplets spread before freezing and make clear ice, hard and heavy, typical in cumuliform cloud and most dangerous. Freezing rain, from rain falling out of warm air into a sub-zero layer below, gives severe clear ice beyond the protected areas. Icing is most likely between about 0 and −15 °C. Ice spoils the airfoil, raising the stall speed and drag and lowering lift, often more than its thickness suggests. Carburettor icing is different: it can occur well above freezing in humid air, because fuel evaporation and the venturi cool the intake air.'}),
I('050-turbulence','050',{title:{en:'Turbulence and mountain waves',no:'Turbulens og fjellbølger'},src:'ch12',lab:'hazards.html',
 kw:'turbulence mechanical turbulence convective turbulence mountain wave lee wave rotor lenticular clear air turbulence cat jet stream turbulens mekanisk turbulens termisk fjellbølge lebølge rotor linseskyer',
 en:'Turbulence comes from convection (rising thermals and cumulus), from the wind flowing over obstacles and rough terrain (mechanical turbulence), from wind shear, and from mountain waves. When a strong wind blows roughly at right angles across a ridge and the air above is stable, waves form downwind that can reach far higher than the mountains; lenticular clouds mark the wave crests, and a rotor with severe turbulence can sit under the crests at about ridge height. On the lee side expect strong downdrafts. Clear-air turbulence occurs without cloud, often near jet streams where the wind changes rapidly with height. In turbulence, fly at the turbulence-penetration speed for the aircraft to protect the structure.'}),
I('050-precipitation','050',{title:{en:'Precipitation and visibility',no:'Nedbør og sikt'},src:'ch12',lab:'clouds.html',
 kw:'precipitation rain drizzle snow showers hail freezing rain sleet visibility haze ice pellets nedbør regn yr snø byger hagl sikt',
 en:'Precipitation forms when cloud droplets or ice crystals grow large enough to fall. Drizzle (small drops) comes from thin stratus; steady rain or snow from deep layer cloud such as nimbostratus; showers and hail from cumuliform cloud. Freezing rain and ice pellets form when precipitation falls through a warm layer and then a sub-zero layer near the ground. All precipitation reduces visibility; snow and drizzle reduce it most for a given intensity. Haze and smoke trapped under an inversion reduce visibility in stable air.'})
];

/* ---------- retrieval: same simple scoring as easa.js, over title + keywords (EN + NO) ---------- */
const norm=s=>String(s||'').toLowerCase().replace(/[‐-―]/g,'-');
const STOP=new Set(('what why how does the and for with that this from into when where which who are was were is its your you can will would should could about there their than then them they have has had not but also only very much more most such some any all each other over under above below what\'s hva hvorfor hvordan er det den som med for til fra på av en et og eller ikke kan skal vil har hvis når hvor jeg meg min mitt mine du deg din dere vi oss var blir ble være mer mest').split(' '));
const HAY=items.map(x=>({x,t:' '+norm(x.title.en+' '+x.title.no).replace(/[^a-z0-9æøå°/ -]/g,' ')+' ',h:' '+norm(x.title.en+' '+x.title.no+' '+x.kw).replace(/[^a-z0-9æøå°/ -]/g,' ')+' '}));
const dfOf=w=>HAY.filter(o=>o.h.includes(' '+w+' ')).length;
function search(q,k){ const t=norm(q); const words=[...new Set(t.replace(/[^a-z0-9æøå°/ -]/g,' ').split(/\s+/).filter(w=>w.length>2&&!STOP.has(w)))];
  if(!words.length) return [];
  const df={}; words.forEach(w=>{ df[w]=dfOf(w); });
  const sc=HAY.map(o=>{ let s=0;
    words.forEach(w=>{ const stem=w.length>=6? w.slice(0,Math.max(5,w.length-3)) : null;
      if(o.h.includes(' '+w+' ')){ s+=2+(df[w]===1?2:df[w]<=3?1:0); if(o.t.includes(' '+w+' ')) s+=1; }
      else if(stem&&o.h.includes(' '+stem)){ s+=1.5; if(o.t.includes(' '+stem)) s+=1; } });
    for(let i=0;i<words.length-1;i++){ if(o.h.includes(' '+words[i]+' '+words[i+1]+' ')) s+=2; }
    return {x:o.x,s}; });
  const top=Math.max(0,...sc.map(o=>o.s)), min=Math.max(2,top*0.5);
  return sc.filter(o=>o.s>=min).sort((a,b)=>b.s-a.s).slice(0,k||3).map(o=>o.x); }
function get(id){ return items.find(x=>x.id===id)||null; }
function lang(){ try{ return (G.LAB&&G.LAB.lang)||(document.documentElement.lang==='nb'?'no':'en'); }catch(e){ return 'en'; } }
const title=(x,l)=>((l||lang())==='no'? x.title.no : x.title.en);

/* text block for the AI prompt; entries are cited as [T1], [T2]… */
function promptBlock(list){ if(!list||!list.length) return '';
  return 'THEORY LIBRARY (NORDAP\'s curated explanations of aviation THEORY, written in EASA/ICAO terms from the FAA Pilot\'s Handbook of Aeronautical Knowledge (a U.S. Government work) and NORDAP\'s Virtual Labs. They explain physics and understanding only):\n\n'+
    list.map((x,i)=>`[T${i+1}] ${x.title.en} (${SUBJ[x.subj].en}; source: ${SRC[x.src].n}${x.lab?'; NORDAP lab: '+x.lab:''}):\n${x.en}`).join('\n\n')+
    '\n\nTHEORY CITATION RULES: when a statement rests on one of the theory entries above, cite it as [T1], [T2] and so on, and prefer these entries over your own knowledge for theory. They are NEVER a source for rules, limits, minima, required equipment or procedures: those come only from EASA entries [E…] or the pilot\'s documents [S…]. If an entry mentions that something is regulated, say that the EASA rules or the AFM decide it. Never bring U.S. (FAA) rules, U.S. airspace classes, U.S. weather categories or °F/inHg into the answer.'; }

const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function chip(x,n){ const l=lang(); const s=SRC[x.src];
  const href= x.lab || s.u; const tip=(l==='no'?'Teori: ':'Theory: ')+title(x,l)+' · '+s.n+(x.lab?(l==='no'?' · åpner labben':' · opens the lab'):'');
  return `<a class="tcite" href="${esc(href)}"${x.lab?'':' target="_blank" rel="noopener"'} title="${esc(tip)}" data-t="${n||''}">${esc(title(x,l))}</a>`; }
/* replace [T1]… in already-escaped HTML with chips */
function cite(html,list){ return String(html).replace(/\[T(\d{1,2})\]/g,(m,n)=>{ const x=list&&list[+n-1]; return x? chip(x,+n) : ''; }); }
const CSS='.tcite{display:inline-block;font:500 11.5px/1.5 var(--f-mono,ui-monospace,monospace);padding:0 6px;margin:0 2px;border-radius:4px;background:#EEF2FF;color:#3730A3;border:1px solid #C7D2FE;text-decoration:none;vertical-align:1px}.tcite:hover{background:#E0E7FF}';
function style(){ try{ if(document.getElementById('tcite-css')) return; const s=document.createElement('style'); s.id='tcite-css'; s.textContent=CSS; document.head.appendChild(s); }catch(e){} }
const API={checked:'2026-11',sources:SRC,subjects:SUBJ,items,search,get,promptBlock,chip,cite,title,style};
if(typeof document!=='undefined') style();
G.THEORY=API;
if(typeof module!=='undefined'&&module.exports) module.exports=API;
})(typeof window!=='undefined'?window:globalThis);
